class Solution {
    public int minimumLengthEncoding(String[] words){
        Set<String> remaining=new HashSet<>(Arrays.asList(words));
        for(String word:words)for(int start=1;start<word.length();start++)remaining.remove(word.substring(start));
        int answer=0;
        for(String word:remaining)answer+=word.length()+1;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minimumLengthEncoding(words:Array<String>):Int{
        val remaining=words.toMutableSet();
        for(word in words)for(start in 1 until word.length)remaining.remove(word.substring(start));
        return remaining.sumOf{
            it.length+1
        }
    }
}

code.cpp:
class Solution {
    public: int minimumLengthEncoding(vector<string>& words){
        unordered_set<string> remaining(words.begin(),words.end());
        for(string& word:words)for(int start=1;start<(int)word.size();++start)remaining.erase(word.substr(start));
        int answer=0;
        for(string word:remaining)answer+=word.size()+1;
        return answer;
    }
};
